import { Injectable } from '@angular/core';

@Injectable()
export class ImageUploadConfig {
	public url: string = 'publish/image';
	public maxFileSize: number = 5 * 1024 * 1024;
	public allowedMimeTypes: string[] = ['image/jpg', 'image/jpeg', 'image/pjpeg', 'image/png', 'image/x-icon', 'image/vnd.microsoft.icon'];
}